+import { App, Request, Response } from "./app";
+import { listUsers, createUser, UserInput } from "./users";
+
+export function registerRoutes(app: App): void {
+  app.get("/api/v1/users", listUsersV1);
+  app.get("/api/v2/users", listUsersV2);
+  app.post("/api/v2/users", createUserV2);
+}
+
+function listUsersV1(_req: Request, res: Response): void {
+  res.json(listUsers());
+}
+
+function listUsersV2(req: Request, res: Response): void {
+  const page = Number(req.query.page ?? 1);
+  const users = listUsers();
+  res.json({ page, items: users.slice((page - 1) * 20, page * 20) });
+}
+
+function createUserV2(req: Request, res: Response): void {
+  const newUser = createUser(req.body as UserInput);
+  res.status(201).json(newUser);
+}

