+export interface User {
+  id: string;
+  name: string;
+}
+
+export interface UserInput {
+  name: string;
+}
+
+const users: User[] = [];
+
+export function listUsers(): User[] {
+  return users;
+}
+
+export function createUser(input: UserInput): User {
+  const user = { id: String(users.length + 1), name: input.name };
+  users.push(user);
+  return user;
+}
